import json
import os
import re
import glob

source_dir = "$SOURCE_DIR"
thirdparty_base = "$THIRDPARTY_DIR"
thirdparty_json = "$thirdparty_json"
libs_config = "$libs_config"
platforms = ["linux-aarch64-gcc940", "linux-aarch64-gcc1330", "linux-x86_64-gcc940"]
all_platforms_token = "all"

# 平台到工具链目录的映射
platform_to_toolchain = {
    "linux-aarch64-gcc940": "gcc940-aarch64-ubuntu2004-gnu",
    "linux-aarch64-gcc1330": "gcc13.3-aarch64-ubuntu2404-gnu",
    "linux-x86_64-gcc940": "gcc940-x86_64-ubuntu2004-gnu"
}

def get_lib_dirs(platform):
    """获取三方库搜索目录列表（按优先级排序）"""
    dirs = []

    # 优先检查 output 目录
    output_lib_dir = os.path.join(source_dir, 'galbot_sdk', platform, 'lib')
    if os.path.isdir(output_lib_dir):
        dirs.append(output_lib_dir)

    # 回退到 ThirdParty 目录
    toolchain = platform_to_toolchain.get(platform)
    if toolchain:
        thirdparty_lib_dir = os.path.join(thirdparty_base, toolchain, 'lib')
        if os.path.isdir(thirdparty_lib_dir):
            dirs.append(thirdparty_lib_dir)

    return dirs

def find_lib_dir_with_pattern(lib_dirs, pattern):
    """在多个目录中查找包含匹配文件的目录"""
    for lib_dir in lib_dirs:
        for p in pattern.split('|'):
            if glob.glob(os.path.join(lib_dir, p.strip())):
                return lib_dir
    return None

def parse_platform_scope(scope_text, line_no):
    """解析平台范围；空值表示所有平台。"""
    if not scope_text:
        return list(platforms)

    raw_items = [item.strip() for item in scope_text.split(',') if item.strip()]
    if not raw_items:
        raise ValueError(f"第 {line_no} 行平台范围为空")

    if len(raw_items) == 1 and raw_items[0].lower() == all_platforms_token:
        return list(platforms)

    invalid = [item for item in raw_items if item not in platforms]
    if invalid:
        raise ValueError(
            f"第 {line_no} 行包含未知平台: {', '.join(invalid)}; "
            f"支持的平台: {', '.join(platforms)}"

